using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using Dreamscape.Characters;
using System.IO;
public static class FivePhaseBuilder {
 static Material plaster,tile,metal,oak,green,glow,blue,gold;static Transform root;static string dir="Assets/Production/Generated";
 static Vector3 V(float x,float y,float z)=>new Vector3(x,y,z);
 static Material Mat(string n,Color c,float metallic=0,float smooth=.3f){var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=c;m.SetFloat("_Metallic",metallic);m.SetFloat("_Smoothness",smooth);AssetDatabase.CreateAsset(m,dir+"/"+n+".mat");return m;}
 static GameObject Box(string n,Vector3 p,Vector3 s,Material m,bool solid=true){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(root);g.transform.position=p;g.transform.localScale=s;g.GetComponent<Renderer>().sharedMaterial=m;if(!solid)Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static GameObject Model(string n,Vector3 p,Quaternion q){var a=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Art/Environment/ArchitecturalKit/"+n+".fbx");var o=(GameObject)PrefabUtility.InstantiatePrefab(a);o.transform.SetParent(root);o.transform.SetPositionAndRotation(p,q);foreach(var r in o.GetComponentsInChildren<Renderer>()){var m=r.name.Contains("diffuser")?glow:r.name.Contains("leaf")?oak:metal;r.sharedMaterial=m;}return o;}
 static void Text(string t,Vector3 p,float size,Color c,Quaternion q){var g=new GameObject(t);g.transform.SetParent(root);g.transform.SetPositionAndRotation(p,q);var m=g.AddComponent<TextMesh>();m.text=t;m.fontSize=80;m.characterSize=size;m.anchor=TextAnchor.MiddleCenter;m.color=c;}
 static void Room(int i,string name,float length){float x=i*40;root=new GameObject("FASE "+(i+1)+" - "+name).transform;
 Box("Back wall",V(x,2.2f,-1),V(10,4.4f,.25f),plaster);Box("Ceiling",V(x,4.4f,length/2),V(10,.2f,length+2),plaster);
 for(int side=-1;side<=1;side+=2){Box("Plaster",V(x+side*5,2.2f,length/2),V(.22f,4.4f,length+2),plaster);Box("Sage dado",V(x+side*4.87f,.65f,length/2),V(.05f,1.3f,length+2),green);Box("Skirting",V(x+side*4.81f,.09f,length/2),V(.05f,.18f,length+2),metal);Box("Dado trim",V(x+side*4.82f,1.32f,length/2),V(.04f,.045f,length+2),oak);
 for(int z=2;z<length;z+=5){Box("Wall pilaster",V(x+side*4.75f,2.2f,z),V(.18f,4.4f,.32f),plaster);Box("Conduit",V(x+side*4.65f,3.8f,z+1.9f),V(.055f,.055f,4.8f),metal);}}
 for(int z=2;z<length;z+=4){Model("FluorescentFixture",V(x,4.25f,z),Quaternion.identity);var l=new GameObject("Fluorescent bounce").AddComponent<Light>();l.transform.SetParent(root);l.transform.position=V(x,3.8f,z);l.type=LightType.Point;l.intensity=3.1f;l.range=7;l.color=new Color(1,.91f,.72f);l.shadows=z==6?LightShadows.Soft:LightShadows.None;}
 Box("Pit foundation",V(x,-5.5f,length/2),V(10,.3f,length),metal);
 Text((i+1).ToString("00")+" / "+name.ToUpper(),V(x,2.6f,-.84f),.075f,new Color(.24f,.30f,.24f),Quaternion.Euler(0,180,0));
 for(int s=-1;s<=1;s+=2){Box("Exit wall",V(x+s*3.1f,2.2f,length),V(3.8f,4.4f,.25f),plaster);}Box("Exit header",V(x,3.5f,length),V(2.4f,1.8f,.25f),plaster);
 Text("SAÍDA",V(x,2.8f,length-.16f),.075f,new Color(.4f,.85f,.6f),Quaternion.identity);
 }
 static GameObject Floor(float x,float z,float w,float len,float top=0){return Box("Terrazzo floor",V(x,top-.18f,z),V(w,.36f,len),tile);}
 static void Pickup(float x,float z,bool jump){var g=GameObject.CreatePrimitive(PrimitiveType.Sphere);g.name=jump?"Pulo duplo":"Velocidade";g.transform.SetParent(root);g.transform.position=V(x,1,z);g.transform.localScale=Vector3.one*.38f;g.GetComponent<Renderer>().sharedMaterial=jump?blue:gold;g.GetComponent<Collider>().isTrigger=true;var rb=g.AddComponent<Rigidbody>();rb.isKinematic=true;var p=g.AddComponent<ProductionMechanism>();p.kind=0;p.jump=jump;Box("Collectible pedestal",V(x,.17f,z),V(.7f,.34f,.7f),metal);var l=g.AddComponent<Light>();l.color=jump?Color.cyan:new Color(1,.6f,.15f);l.intensity=1.5f;l.range=3;}
 static void Trap(float x,float z,float delay){var f=Floor(x,z,2.1f,1.6f);f.name="Temporary floor";Model("BoltedFloorPlate",V(x,.015f,z),Quaternion.identity).transform.SetParent(f.transform,true);var g=new GameObject("Plate sensor");g.transform.SetParent(root);g.transform.position=V(x,.25f,z);var c=g.AddComponent<BoxCollider>();c.isTrigger=true;c.size=V(2,.5f,1.5f);g.AddComponent<Rigidbody>().isKinematic=true;var p=g.AddComponent<ProductionMechanism>();p.kind=1;p.delay=delay;p.moving=f.transform;}
 static ProductionMechanism Door(float x,float z,float y=0){Model("DoorFrame",V(x,y,z),Quaternion.identity);var g=Box("Sliding door",V(x,y+1.1f,z),V(1.05f,2.2f,.15f),oak);Model("DoorLeaf",V(x,y,z-.1f),Quaternion.identity).transform.SetParent(g.transform,true);var m=g.AddComponent<ProductionMechanism>();m.kind=3;m.moving=g.transform;return m;}
 static void Button(float x,float y,float z,ProductionMechanism door){Box("Button housing",V(x,y,z),V(.42f,.52f,.15f),metal);var b=Box("Interaction button",V(x,y,z-.1f),V(.22f,.22f,.10f),gold);var m=b.AddComponent<ProductionMechanism>();m.kind=2;m.linked=door;}
 [MenuItem("Dreamscape/Produção/Abrir cinco fases")]
 public static void Open(){EditorSceneManager.OpenScene("Assets/Scenes/Dreamscape_CincoFases.unity");}
 public static void Build(){Directory.CreateDirectory(dir);AssetDatabase.Refresh();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
 plaster=Mat("Plaster",new Color(.71f,.68f,.58f));tile=Mat("Terrazzo",new Color(.47f,.46f,.40f),0,.38f);metal=Mat("Graphite",new Color(.16f,.19f,.18f),.65f,.38f);oak=Mat("Oak",new Color(.35f,.23f,.12f));green=Mat("Sage",new Color(.29f,.37f,.32f));blue=Mat("Blue power",new Color(.05f,.65f,.85f),.3f);gold=Mat("Amber",new Color(.95f,.48f,.08f),.3f);glow=Mat("Fluorescent",new Color(.9f,.91f,.79f));glow.EnableKeyword("_EMISSION");glow.SetColor("_EmissionColor",new Color(1,.91f,.74f)*2);
 // Terrazzo grain and grout at real-world scale.
 var texture=new Texture2D(256,256);var rand=new System.Random(73);for(int y=0;y<256;y++)for(int x=0;x<256;x++){float v=.87f+(float)rand.NextDouble()*.15f;if(rand.NextDouble()<.07)v*=.62f;if(x<2||y<2)v*=.65f;texture.SetPixel(x,y,new Color(v,v,v));}texture.Apply();texture.wrapMode=TextureWrapMode.Repeat;AssetDatabase.CreateAsset(texture,dir+"/Terrazzo.asset");tile.mainTexture=texture;tile.mainTextureScale=new Vector2(6,6);
 var starts=new Vector3[5];var exits=new Vector3[5];string[] names={"Saída fácil","Pressa pra quê","Portas parecidas","Moema abre caminho","Olhe o chão"};
 for(int i=0;i<5;i++){float x=i*40;float len=i==3?16:24;Room(i,names[i],len);starts[i]=V(x,.05f,1);exits[i]=V(x,.05f,len+1.2f);Floor(x,1.5f,10,5);Floor(x,len-1,10,6);Floor(x,len+1.5f,2,3);
 if(i==0){Pickup(x-2,3,true);for(int k=0;k<4;k++){float h=.5f*k;Floor(x-3,6+k*4,2.2f,2.1f,h);Box("Platform rim",V(x-3,h+.03f,5+k*4),V(2.2f,.06f,.12f),metal);}for(int k=0;k<7;k++)Trap(x,5+k*1.6f,.18f);Floor(x,21,10,4,1.5f);Floor(x,23,2,3,.75f);exits[i]=V(x,.05f,25.2f);}
 if(i==1){Pickup(x-2,3,false);Floor(x-3,8.5f,2.2f,10);Box("Low service beam",V(x-3,1.75f,10),V(2.3f,1.2f,.65f),metal);for(int k=0;k<5;k++)Trap(x-3,14.5f+k*1.6f,.7f);Floor(x,7,2,5);}
 if(i==2){Floor(x,12,10,24);Pickup(x-2,3,true);Floor(x+3,13,2.2f,2.2f,1.5f);var door=Door(x,23.9f);Button(x+3,2.4f,13.8f,door);for(int s=-1;s<=1;s+=2){Door(x+s*3,20);Box("Dead end",V(x+s*3,1.7f,22),V(2.3f,3.4f,.2f),plaster);Text("ARQUIVO",V(x+s*3,2.8f,19.7f),.045f,Color.white,Quaternion.identity);}}
 if(i==3){Floor(x,8,10,18);var d=Door(x,15.9f);for(int s=-1;s<=1;s+=2)for(int k=0;k<4;k++)Model("StorageShelf",V(x+s*4,0,3+k*2.7f),Quaternion.Euler(0,s*90,0));Box("Moema plinth",V(x,.14f,8),V(1.5f,.28f,1.5f),metal);var a=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Art/Characters/Moema/Moema.fbx");var mo=(GameObject)PrefabUtility.InstantiatePrefab(a);mo.transform.SetParent(root);mo.transform.position=V(x,.28f,8);foreach(var r in mo.GetComponentsInChildren<Renderer>())r.sharedMaterial=blue;Button(x,.9f,6.8f,d);}
 if(i==4){Pickup(x-2,3,false);for(int k=0;k<9;k++)Trap(x,5.5f+k*1.6f,.8f);for(int k=0;k<4;k++){Floor(x-3,6+k*4,2.1f,2.3f);Floor(x-1.5f,6+k*4,2,1.2f);Box("Safe edge",V(x-3,.03f,5+k*4),V(2.1f,.05f,.1f),gold);}}
 }
 var player=new GameObject("Carlinhos - Player");player.tag="Player";var cc=player.AddComponent<CharacterController>();cc.height=1.76f;cc.center=V(0,.88f,0);cc.radius=.24f;cc.stepOffset=.28f;var motor=player.AddComponent<CharacterMotor>();player.AddComponent<PlayerInputController>();player.transform.position=starts[0];var cam=new GameObject("First person camera").AddComponent<Camera>();cam.tag="MainCamera";cam.fieldOfView=72;cam.nearClipPlane=.04f;cam.farClipPlane=80;cam.gameObject.AddComponent<AudioListener>();var fp=cam.gameObject.AddComponent<Dreamscape.CameraSystem.FirstPersonCamera>();var so=new SerializedObject(fp);so.FindProperty("target").objectReferenceValue=cc;so.ApplyModifiedPropertiesWithoutUndo();cam.gameObject.AddComponent<UniversalAdditionalCameraData>().renderPostProcessing=true;
 var campaign=new GameObject("Campaign").AddComponent<DreamscapeCampaign>();campaign.player=motor;campaign.starts=starts;campaign.exits=exits;campaign.titles=names;campaign.view=cam;
 RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.38f,.4f,.36f);RenderSettings.ambientEquatorColor=new Color(.23f,.25f,.22f);RenderSettings.ambientGroundColor=new Color(.13f,.14f,.12f);RenderSettings.fog=true;RenderSettings.fogColor=new Color(.24f,.27f,.24f);RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogDensity=.012f;
 var vol=new GameObject("Color and lens").AddComponent<Volume>();vol.isGlobal=true;vol.sharedProfile=ScriptableObject.CreateInstance<VolumeProfile>();vol.sharedProfile.Add<Tonemapping>().mode.Override(TonemappingMode.ACES);var ca=vol.sharedProfile.Add<ColorAdjustments>();ca.postExposure.Override(.5f);ca.contrast.Override(12);ca.saturation.Override(-8);vol.sharedProfile.Add<Bloom>().intensity.Override(.18f);vol.sharedProfile.Add<Vignette>().intensity.Override(.16f);AssetDatabase.CreateAsset(vol.sharedProfile,dir+"/Look.asset");
 EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/Scenes/Dreamscape_CincoFases.unity");AssetDatabase.SaveAssets();
 }
}
